        -- 娣诲姞鍚戝墠閫熷害/鍒硅溅
        if self.PlayerState.IsCanMove then
            self.PlayerState.DriveCar:MoveForward(1);
            self.PlayerState.DriveCar:SetHandBrake(0);
        else
            self.PlayerState.DriveCar:MoveForward(0);
            self.PlayerState.DriveCar:SetHandBrake(1);
        end
    end
    if not self:HasAuthority() then 
        if self.PlayerState and self.PlayerState.DriveCar and self.PlayerState.CurrentRoadSegmentDir ~= nil then
            -- 閫嗗悜妫€娴?瀹㈡埛绔嚜琛屽垽鏂?
            local RoadSegmentDir;
            if UGCGameSystem.GameState.IsSplineReverse then
                RoadSegmentDir = VectorHelper.MulNumber(self.PlayerState.CurrentRoadSegmentDir, -1);
            else
                RoadSegmentDir = self.PlayerState.CurrentRoadSegmentDir;
            end
            local Angle = VectorHelper.GetAngle2D(self.PlayerState.DriveCar.Mesh:GetForwardVector(),RoadSegmentDir);
            ugcprint("CurrentAngle is :" .. tostring(Angle));
            if Angle > 120 then
                self.CurrentReverseDriveTime = self.CurrentReverseDriveTime + DeltaTime;
                if self.CurrentReverseDriveTime > self.MaxReverseDriveTime then
                    UnrealNetwork.CallUnrealRPC(self, self, "ServerRPC_ResetVehicle");
                    self.CurrentReverseDriveTime = 0;
                end
                ugcprint("self.CurrentReverseDriveTime is :" .. tostring(self.CurrentReverseDriveTime));
            else
                self.CurrentReverseDriveTime = 0;
            end
        end
    end
end

