function UGCPlayerController:GarageSelectCar(index)
    ugcprint("UGCPlayerController:GarageSelectCar index : " .. index)

    if self.GarageSelectedCarIndex ~= -1 then
        local LastCar = self.GarageCarList[self.GarageSelectedCarIndex]
        local LastCarLocation = LastCar:K2_GetActorLocation()
        LastCar:K2_TeleportTo({X = LastCarLocation.X -self.GarageSelectedCarOffsetX , Y = LastCarLocation.Y , Z = LastCarLocation.Z},LastCar:K2_GetActorRotation())
    end

    local currCar = self.GarageCarList[index]
    if not currCar then
        ugcprint("UGCPlayerController:GarageSelectCar ERROR : car is nil which index is :" .. index)
        return
    end
    self.GarageSelectedCarIndex = index
    local carLocaction = currCar:K2_GetActorLocation()
    ugcprint("UGCPlayerController:GarageSelectCar orginLoc : " .. VectorHelper.ToString(carLocaction))

    currCar:K2_TeleportTo({X = carLocaction.X +self.GarageSelectedCarOffsetX , Y = carLocaction.Y , Z = carLocaction.Z},currCar:K2_GetActorRotation())


    local cameraLocation = self.GarageCamera:K2_GetActorLocation()
    self.GarageCamera:K2_SetActorLocation({X = cameraLocation.X , Y = carLocaction.Y , Z = cameraLocation.Z})
end

